<script setup lang="ts">
import {ref,reactive,computed,onMounted} from 'vue'
import {api,can,session} from './session'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useTableWidths} from './tableWidths'
const widths=useTableWidths('CompliancePanel'),rows=ref<any[]>([]),stores=ref<string[]>([]),busy=ref(false),error=ref(''),dialog=ref(false),editing=ref<any>(),form=reactive<any>({})
const query=reactive({store:'',kind:''}),applied=reactive({store:'',kind:''})
const visible=computed(()=>rows.value.filter(r=>r.store.toLowerCase().includes(applied.store.trim().toLowerCase())&&(!applied.kind||r.kind===applied.kind)))
const names:Record<string,string>={UK:'英国',DE:'德国',FR:'法国',ES:'西班牙',IT:'意大利',NL:'荷兰',BE:'比利时',PL:'波兰',SE:'瑞典',IE:'爱尔兰',AT:'奥地利',CZ:'捷克',DK:'丹麦',FI:'芬兰',PT:'葡萄牙',LU:'卢森堡',GR:'希腊',HU:'匈牙利',RO:'罗马尼亚',BG:'保加利亚',HR:'克罗地亚',CY:'塞浦路斯',EE:'爱沙尼亚',LV:'拉脱维亚',LT:'立陶宛',MT:'马耳他',SK:'斯洛伐克',SI:'斯洛文尼亚',NO:'挪威',CH:'瑞士',US:'美国',CA:'加拿大',AU:'澳大利亚',JP:'日本',AE:'阿联酋',SA:'沙特',CN:'中国'}
const typeNames:Record<string,string>={UK:"英代",EU:"欧代",VAT:"VAT"}
const fields:Record<string,string>={representative_name:'代理联系人',representative_company:'代理公司',representative_email:'代理邮箱',representative_address:'代理地址',manufacturer_company:'制造商名称',manufacturer_email:'制造商邮箱',manufacturer_address:'制造商地址'}
async function load(){busy.value=true;error.value='';try{const [options,profiles,vat]=await Promise.all([api('/options'),api('/shipping/profiles'),api('/settings/profiles/vat')]);stores.value=options.stores;rows.value=[...profiles.rows.map((r:any)=>({...r,kind:r.country==='UK'?'UK':'EU'})),...vat.rows.map((r:any)=>({...r,kind:'VAT'}))]}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function search(){Object.assign(applied,query)}
function reset(){Object.assign(query,{store:'',kind:''});search()}
function edit(row?:any){editing.value=row;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{kind:row?.kind||'UK',store:row?.store||session.value?.current_store||stores.value[0],country:row?.country||'UK',revision:row?.revision||0,vat:row?.vat||'',eori:row?.eori||'',tax_agent_address:row?.tax_agent_address||'',representative_expires:null,show_marks:true,...row?.detail});for(const k in fields)form[k]??='';dialog.value=true}
function changeKind(){if(form.kind!=='VAT')form.country=form.kind;else if(form.country==='EU')form.country='DE'}
async function save(){busy.value=true;try{const payload=form.kind==='VAT'?Object.fromEntries(['store','country','revision','vat','eori','tax_agent_address'].map(k=>[k,form[k]])):{store:form.store,country:form.kind,revision:form.revision,...Object.fromEntries(Object.keys(fields).map(k=>[k,form[k]])),representative_expires:form.representative_expires,show_marks:form.show_marks};await api(form.kind==='VAT'?'/settings/profiles/vat':'/shipping/profiles',payload);dialog.value=false;await load();ElMessage.success('已保存')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function remove(row:any){try{await ElMessageBox.confirm('确定删除这条合规信息？','删除');await api(row.kind==='VAT'?'/settings/profiles/vat/delete':'/shipping/profiles/remove-record',{store:row.store,country:row.country,revision:row.revision});await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
onMounted(load)
</script>
<template><section class="compliance-panel"><form class="compliance-tools" @submit.prevent="search"><el-input v-model="query.store" aria-label="合规店铺名称" placeholder="搜索店铺名称" clearable @clear="search"/><el-select v-model="query.kind" aria-label="合规信息类型" placeholder="全部类型" clearable><el-option label="英代" value="UK"/><el-option label="欧代" value="EU"/><el-option label="VAT" value="VAT"/></el-select><el-button type="primary" native-type="submit">查询</el-button><el-button @click="reset">重置</el-button><el-button @click="load">刷新</el-button><el-button v-if="can('settings.profiles','operate')" type="primary" @click="edit()">新增合规信息</el-button><TableReset table-key="CompliancePanel/records"/></form><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<el-table :data="visible" v-loading="busy" border data-width-key="CompliancePanel/records" @header-dragend="(w:number,_:number,c:any)=>widths.resize('records',w,c)">
<el-table-column prop="store" label="店铺" column-key="store" :width="widths.width('records','store',160)"/><el-table-column label="类型" column-key="kind" :width="widths.width('records','kind',90)"><template #default="{row}">{{typeNames[row.kind]}}</template></el-table-column><el-table-column label="国家 / 地区" column-key="country" :width="widths.width('records','country',120)"><template #default="{row}">{{names[row.country]||(row.country==='EU'?'欧盟':row.country)}}</template></el-table-column><el-table-column prop="vat" label="VAT" column-key="vat" :width="widths.width('records','vat',180)"/><el-table-column prop="eori" label="EORI号" column-key="eori" :width="widths.width('records','eori',180)"/><el-table-column label="代理 / 税务代理地址" column-key="agent" :width="widths.width('records','agent',320)"><template #default="{row}"><template v-if="row.kind==='VAT'">{{row.tax_agent_address}}</template><template v-else>{{row.detail.representative_company}}<br>{{row.detail.representative_address}}</template></template></el-table-column><el-table-column label="资料检查" column-key="check" :width="widths.width('records','check',220)"><template #default="{row}">{{row.kind==='VAT'?'—':row.missing?.length?'缺少：'+row.missing.join('、'):'完整'}}</template></el-table-column><el-table-column v-if="can('settings.profiles','operate')" label="操作" column-key="actions" :width="widths.width('records','actions',140)" fixed="right"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
<el-dialog v-model="dialog" :title="editing?'编辑合规信息':'新增合规信息'" width="min(760px,95vw)" :close-on-click-modal="false"><el-form label-position="top" :disabled="busy" class="compliance-form"><el-form-item label="店铺"><el-select v-model="form.store" :disabled="!!editing" aria-label="合规店铺"><el-option v-for="s in stores" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item label="类型"><el-select v-model="form.kind" :disabled="!!editing" aria-label="新增合规类型" @change="changeKind"><el-option label="英代" value="UK"/><el-option label="欧代" value="EU"/><el-option label="VAT" value="VAT"/></el-select></el-form-item><template v-if="form.kind==='VAT'"><el-form-item label="国家"><el-select v-model="form.country" :disabled="!!editing" filterable allow-create default-first-option placeholder="选择国家或输入两位国家代码" aria-label="VAT国家"><el-option v-for="(name,key) in names" :key="key" :value="key" :label="name+' · '+key"/></el-select></el-form-item><el-form-item label="VAT"><el-input v-model="form.vat" aria-label="VAT号" maxlength="100"/></el-form-item><el-form-item label="EORI号"><el-input v-model="form.eori" aria-label="EORI号" maxlength="100"/></el-form-item><el-form-item label="税务代理地址"><el-input v-model="form.tax_agent_address" type="textarea" :rows="3" maxlength="2000"/></el-form-item></template><template v-else><el-form-item v-for="(label,key) in fields" :key="key" :label="label"><el-input v-model="form[key]" :type="key.includes('address')?'textarea':'text'"/></el-form-item><el-form-item label="到期日期"><el-date-picker v-model="form.representative_expires" value-format="YYYY-MM-DD"/></el-form-item><el-checkbox v-model="form.show_marks">打印14+、回收、CE、UKCA图标</el-checkbox></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.compliance-tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.compliance-tools>.el-input{width:240px}.compliance-tools>.el-select{width:160px}.compliance-form{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.compliance-form .el-select{width:100%}@media(max-width:640px){.compliance-form{grid-template-columns:1fr}}</style>
